function transform(message, context) {
  var p = message.payload || {};
  var registrationId = p.registrationId;
  var permitType = p.permitType;

  if (!registrationId) {
    throw new Error('registrationId is required');
  }
  if (String(registrationId).length > 20) {
    throw new Error('registrationId must be 20 characters or fewer (Authorize.net invoiceNumber limit)');
  }
  if (!permitType) {
    throw new Error('permitType is required');
  }

  context.set('registrationId', String(registrationId));
  context.set('permitType', String(permitType));
  return message;
}

function transform(message, context) {
  // Server-side fee schedule — amount is never taken from the caller.
  // TODO: replace placeholder amounts with real permit fees before go-live.
  var FEE_SCHEDULE = {
    'full-year':  { amount: '125.00', label: 'Full-Year Permit' },
    'fall':       { amount: '75.00',  label: 'Fall Semester Permit' },
    'spring':     { amount: '75.00',  label: 'Spring Semester Permit' },
    'summer':     { amount: '40.00',  label: 'Summer Permit' },
    'motorcycle': { amount: '50.00',  label: 'Motorcycle Permit' }
  };

  var permitType     = context.get('permitType');
  var registrationId = context.get('registrationId');
  var fee = FEE_SCHEDULE[permitType];
  if (!fee) {
    throw new Error('Unknown permit type: ' + permitType);
  }

  var production = (context.environment === 'production');
  context.set('apiUrl', production
    ? 'https://api.authorize.net/xml/v1/request.api'
    : 'https://apitest.authorize.net/xml/v1/request.api');
  context.set('formUrl', production
    ? 'https://accept.authorize.net/payment/payment'
    : 'https://test.authorize.net/payment/payment');
  context.set('amount', fee.amount);
  context.set('feeLabel', fee.label);

  // Redirect mode: hosted page opens in its own tab and shows the Authorize.net receipt.
  message.payload = {
    getHostedPaymentPageRequest: {
      merchantAuthentication: {
        name: context.authNetLoginId,
        transactionKey: context.authNetTransactionKey
      },
      transactionRequest: {
        transactionType: 'authCaptureTransaction',
        amount: fee.amount,
        order: {
          invoiceNumber: registrationId,
          description: fee.label
        }
      },
      hostedPaymentSettings: {
        setting: [
          {
            settingName: 'hostedPaymentReturnOptions',
            settingValue: JSON.stringify({ showReceipt: true })
          },
          {
            settingName: 'hostedPaymentButtonOptions',
            settingValue: JSON.stringify({ text: 'Pay' })
          },
          {
            settingName: 'hostedPaymentOrderOptions',
            settingValue: JSON.stringify({ show: true, merchantName: context.merchantName || 'Methodist University' })
          },
          {
            settingName: 'hostedPaymentBillingAddressOptions',
            settingValue: JSON.stringify({ show: true, required: false })
          }
        ]
      }
    }
  };
  return message;
}

function transform(message, context) {
  var raw = message.payload;
  // Authorize.net prepends a UTF-8 BOM on JSON responses; strip before parsing.
  if (typeof raw === 'string') {
    raw = JSON.parse(raw.replace(/^\uFEFF/, '').trim());
  }

  var msgs = (raw && raw.messages) ? raw.messages : {};
  if ((msgs.resultCode || '').toLowerCase() !== 'ok' || !raw.token) {
    var m = (msgs.message && msgs.message[0]) || {};
    throw new Error('getHostedPaymentPage failed: [' + m.code + '] ' + m.text);
  }

  return {
    token:       raw.token,
    formUrl:     context.get('formUrl'),
    amount:      context.get('amount'),
    description: context.get('feeLabel'),
    environment: context.environment
  };
}
